  ME: "Northeast", NH: "Northeast", VT: "Northeast", MA: "Northeast", RI: "Northeast",
  CT: "Northeast", NY: "Northeast", NJ: "Northeast", PA: "Northeast", MD: "Northeast",
  DE: "Northeast", DC: "Northeast",
  OH: "Midwest", MI: "Midwest", IN: "Midwest", IL: "Midwest", WI: "Midwest",
  MN: "Midwest", IA: "Midwest", NE: "Midwest", ND: "Midwest", SD: "Midwest",
  MO: "Midwest", KS: "Midwest",
  CO: "Mountain & West", AZ: "Mountain & West", NV: "Mountain & West", UT: "Mountain & West",
  OK: "Mountain & West", NM: "Mountain & West", MT: "Mountain & West", ID: "Mountain & West",
  WY: "Mountain & West", CA: "Mountain & West", OR: "Mountain & West", WA: "Mountain & West",
